// swift-tools-version:6.4
import PackageDescription

// One module per area of the App Store Connect API, generated by `OpenAPIGenerator generate`.
// Must match the areas in Sources/OpenAPI/modules.json (checked by PackageManifestTests).
let areaModules = [
    "AlternativeDistribution",
    "AppClips",
    "AppStore",
    "AssetLibrary",
    "BackgroundAssets",
    "CustomerReviews",
    "GameCenter",
    "InAppEvents",
    "InAppPurchases",
    "PricingAndAvailability",
    "ProductPages",
    "Provisioning",
    "Reports",
    "StoreMedia",
    "Subscriptions",
    "TestFlight",
    "UsersAndAccess",
    "Webhooks",
    "XcodeCloud",
]

var dependencies: [Package.Dependency] = [
    .package(url: "https://github.com/CreateAPI/URLQueryEncoder.git", from: "0.2.0"),
    .package(url: "https://github.com/apple/swift-crypto.git", from: "4.0.0"),
    .package(url: "https://github.com/apple/swift-argument-parser", from: "1.7.0"),
    .package(url: "https://github.com/weichsel/ZIPFoundation", from: "0.9.20"),
    .package(url: "https://github.com/apple/swift-collections.git", .upToNextMinor(from: "1.1.0"))
]

var coreDependencies: [Target.Dependency] = [
    .product(name: "URLQueryEncoder", package: "URLQueryEncoder"),
    .product(name: "Crypto", package: "swift-crypto")
]

#if os(Linux)
dependencies.append(.package(url: "https://github.com/OpenCombine/OpenCombine.git", from: "0.14.0"))
coreDependencies.append(.product(name: "OpenCombine", package: "OpenCombine"))
#endif

let generatedRoot = "Sources/OpenAPI/Generated"

let areaTargets: [Target] = areaModules.map { area in
    .target(
        name: "AppStoreConnect\(area)",
        dependencies: [
            "AppStoreConnectCore",
            .product(name: "URLQueryEncoder", package: "URLQueryEncoder"),
        ],
        path: "\(generatedRoot)/\(area)"
    )
}

let areaProducts: [Product] = areaModules.map { area in
    .library(name: "AppStoreConnect\(area)", targets: ["AppStoreConnect\(area)"])
}

let umbrellaDependencies: [Target.Dependency] = ["AppStoreConnectCore"] + areaModules.map { area in
    .target(name: "AppStoreConnect\(area)")
}

let package = Package(
    name: "AppStoreConnect-Swift-SDK",
    platforms: [
        .iOS(.v15),
        .macOS(.v12),
        .tvOS(.v15),
        .watchOS(.v9),
    ],
    products: [
        // Everything, as one import. Unchanged for existing users.
        .library(name: "AppStoreConnect-Swift-SDK", targets: ["AppStoreConnect-Swift-SDK"]),
        .library(name: "AppStoreConnectCore", targets: ["AppStoreConnectCore"]),
    ] + areaProducts,
    dependencies: dependencies,
    targets: [
        .testTarget(
            name: "AppStoreConnect-Swift-SDK-Tests",
            dependencies: [
                "AppStoreConnect-Swift-SDK",
                .target(name: "OpenAPIGeneratorCore", condition: .when(platforms: [.macOS])),
            ],
            path: "Tests"
        ),
        .target(
            name: "AppStoreConnectCore",
            dependencies: coreDependencies,
            path: "Sources",
            exclude: [
                "OpenAPI/app_store_connect_api.json",
                "OpenAPI/create-api.yml",
                "OpenAPI/modules.json",
            ],
            sources: [
                "APIProvider.swift",
                "DefaultRequestExecutor.swift",
                "Endpoint.swift",
                "PagedRequest.swift",
                "RateLimit.swift",
                "RequestExecutor.swift",
                "Result.swift",
                "Extensions",
                "JWT",
                "OpenAPI/MetricDimensionData.swift",
                "OpenAPI/Generated/Core",
            ]
        ),
        .target(
            name: "AppStoreConnect-Swift-SDK",
            dependencies: umbrellaDependencies,
            path: "\(generatedRoot)/Umbrella"
        ),
        .target(
            name: "OpenAPIGeneratorCore",
            dependencies: [
                .product(name: "ZIPFoundation", package: "ZIPFoundation"),
                .product(name: "OrderedCollections", package: "swift-collections"),
            ],
            path: "Tools/OpenAPIGeneratorCore"
        ),
        .executableTarget(
            name: "OpenAPIGenerator",
            dependencies: [
                "OpenAPIGeneratorCore",
                .product(name: "ArgumentParser", package: "swift-argument-parser"),
            ],
            path: "Tools/OpenAPIGenerator"
        ),
        .binaryTarget(
            name: "create-api", // Find the URL and checksum at https://github.com/createapi/createapi/releases/latest
            url: "https://github.com/CreateAPI/CreateAPI/releases/download/0.2.0/create-api.artifactbundle.zip",
            checksum: "6f8a3ce099f07eb2655ccaf6f66d8c9a09b74bb2307781c4adec36609ddac009"
        ),
        .plugin(
            name: "CreateAPI",
            capability: .command(
                intent: .custom(
                    verb: "generate-open-api",
                    description: "Generates the OpenAPI entities and paths using CreateAPI"
                ),
                permissions: [
                    .writeToPackageDirectory(reason: "To output the generated source code")
                ]
            ),
            dependencies: [
                .target(name: "create-api")
            ]
        ),
    ] + areaTargets,
    swiftLanguageModes: [.v6]
)
